  `mileage` int(11) DEFAULT NULL,
  `horsepower` int(11) DEFAULT NULL,
  `gearbox` enum('manual','automatic') DEFAULT NULL,
  `location` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `url` varchar(500) DEFAULT NULL,
  `matched_keywords` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`matched_keywords`)),
  `vehicle_id` int(11) DEFAULT NULL,
  `scraped_at` datetime DEFAULT current_timestamp(),
  `fuel_type` varchar(50) DEFAULT NULL,
  `doors` int(11) DEFAULT NULL,
  `seats` int(11) DEFAULT NULL,
  `color` varchar(50) DEFAULT NULL,
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`images`)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lbc_id` (`lbc_id`),
  KEY `vehicle_id` (`vehicle_id`),
  KEY `idx_price` (`price`),
  KEY `idx_year` (`year`),
  KEY `idx_mileage` (`mileage`),
  KEY `idx_scraped_at` (`scraped_at`),
  CONSTRAINT `listings_ibfk_1` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`id`) ON DELETE SET NULL
