CREATE TABLE `vehicles` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `brand` varchar(100) NOT NULL,
  `model` varchar(100) NOT NULL,
  `year_start` int(11) DEFAULT NULL,
  `year_end` int(11) DEFAULT NULL,
  `reliability_score` tinyint(4) DEFAULT NULL,
  `total_testimonials` int(11) DEFAULT 0,
  `common_issues` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`common_issues`)),
  `known_issues_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`known_issues_text`)),
  `source_url` varchar(500) DEFAULT NULL,
  `fuel_type` varchar(50) DEFAULT NULL,
  `scraped_at` datetime DEFAULT current_timestamp(),
  `reliability_rank` varchar(20) DEFAULT NULL COMMENT 'Ranking from fiches-auto.fr: e.g. 1/20 citadines',
  `category` varchar(50) DEFAULT NULL COMMENT 'Categorie fiches-auto',
  `rank_in_category` int(11) DEFAULT NULL,
  `total_in_category` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_brand_model` (`brand`,`model`)
) ENGINE=InnoDB AUTO_INCREMENT=1254 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
